-- =====================================================================================================================================
-- GENERATED by tools/gen-module-tables.mjs from the field registry, then reviewed. One table per business object (the core objects are
-- hand-designed in V1-V7). Same conventions everywhere: community-scoped, typed columns, composite foreign keys, server-stamped
-- metadata, `custom jsonb` for community-defined fields, row-level security (V90).
-- Choice lists ("select" fields) are plain text here because communities can edit them in Studio: the application validates them
-- against field_policies / custom_field_defs. Foreign keys are declared at the end, once every table exists.
-- =====================================================================================================================================

-- Ticket Quick Phrases  (collection: quickPhrases)
CREATE TABLE quick_phrases (
  id                           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  community_id                 uuid NOT NULL REFERENCES communities (id),
  ref_no                       text,                                  -- the number people quote (from number_series)
  phrase                       text NOT NULL,   -- Phrase
  category                     text,   -- Sets category
  custom                       jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(custom) = 'object'),
  created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid, version integer NOT NULL DEFAULT 0,
  UNIQUE (community_id, id)
);
CREATE UNIQUE INDEX quick_phrases_ref ON quick_phrases (community_id, ref_no) WHERE ref_no IS NOT NULL;
CREATE INDEX quick_phrases_recent ON quick_phrases (community_id, created_at DESC);
SELECT use_row_stamps('quick_phrases');

