-- Deposits & Investments  (collection: deposits)
CREATE TABLE deposits (
  id                           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  community_id                 uuid NOT NULL REFERENCES communities (id),
  ref_no                       text,                                  -- the number people quote (from number_series)
  account                      text NOT NULL,   -- Held with account
  type                         text NOT NULL,   -- Type
  amount                       numeric(16,4) NOT NULL CHECK (amount >= 0),   -- Amount
  rate                         numeric(16,4),   -- Interest rate (% a year)
  start_date                   date,   -- Started on
  maturity_date                date,   -- Matures on
  status                       text,   -- Status
  reference                    text,   -- Deposit no. / reference
  interest_payout              text,   -- Interest paid
  auto_renew                   boolean NOT NULL DEFAULT false,   -- Renews automatically at maturity
  sweep_limit                  numeric(16,4),   -- Sweep-in: account balance kept before money moves to / from the deposi
  interest_earned              numeric(16,4),   -- Interest earned so far
  tax_deducted                 numeric(16,4),   -- Tax deducted at source on that interest (TDS)
  notes                        text,   -- Notes
  custom                       jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(custom) = 'object'),
  created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid, version integer NOT NULL DEFAULT 0,
  UNIQUE (community_id, id)
);
CREATE UNIQUE INDEX deposits_ref ON deposits (community_id, ref_no) WHERE ref_no IS NOT NULL;
CREATE INDEX deposits_recent ON deposits (community_id, created_at DESC);
CREATE INDEX deposits_start_date ON deposits (community_id, start_date);
CREATE INDEX deposits_maturity_date ON deposits (community_id, maturity_date);
CREATE INDEX deposits_status ON deposits (community_id, status);
SELECT use_row_stamps('deposits');

