-- Finance Estimates  (collection: financeSettings)
CREATE TABLE finance_settings (
  id                           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  community_id                 uuid NOT NULL REFERENCES communities (id),
  ref_no                       text,                                  -- the number people quote (from number_series)
  on_hand                      text,   -- Accounts counted as on hand
  clubhouse                    numeric(16,4),   -- Facility / hall income still to come
  interest                     numeric(16,4),   -- Interest still to come
  water                        numeric(16,4),   -- Water billing still to come
  dg                           numeric(16,4),   -- DG / generator billing still to come
  emergency                    numeric(16,4),   -- Emergency fund held back
  others                       numeric(16,4),   -- Other items still to pay
  reminder_enabled             boolean NOT NULL DEFAULT false,   -- Send payment reminders automatically
  reminder_every_days          numeric(16,4),   -- Reminder: repeat every (days)
  reminder_lead_days           numeric(16,4),   -- Reminder: start days before due date
  reminder_max                 numeric(16,4),   -- Reminder: stop after
  late_fee_enabled             boolean NOT NULL DEFAULT false,   -- Charge late fees
  late_fee_kind                text,   -- Late fee: fixed amount or % per month
  late_fee_value               numeric(16,4) CHECK (late_fee_value >= 0),   -- Late fee: amount or %
  late_fee_grace_days          numeric(16,4),   -- Late fee: grace days
  late_fee_max_months          numeric(16,4),   -- Late fee: stop after (months)
  late_fee_rules               text,   -- Late fee rules (one per bill type)
  late_fee_auto                boolean NOT NULL DEFAULT false,   -- Late fee: add automatically each month
  block_defaulters             boolean NOT NULL DEFAULT false,   -- No amenity booking for defaulters
  block_overdue_days           numeric(16,4),   -- Defaulter: days overdue
  block_overdue_amount         numeric(16,4) CHECK (block_overdue_amount >= 0),   -- Defaulter: overdue amount above
  locked_until                 date,   -- Books closed up to
  approval_limit               numeric(16,4),   -- Payments above this need a second approver (₹)
  approval_separate            boolean NOT NULL DEFAULT false,   -- Approvers must be different people
  allow_override               boolean NOT NULL DEFAULT false,   -- Super Admin may change the approvals of one task
  final_can_decide_ec          boolean NOT NULL DEFAULT false,   -- Final approvers who are also EC members may give the EC decision
  invoice_skip_within_quote    boolean NOT NULL DEFAULT false,   -- Invoices within the approved amount need no approval
  invoice_tolerance_pct        numeric(16,4),   -- Invoice may exceed the approved amount by (%)
  custom                       jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(custom) = 'object'),
  created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid, version integer NOT NULL DEFAULT 0,
  UNIQUE (community_id, id)
);
CREATE UNIQUE INDEX finance_settings_ref ON finance_settings (community_id, ref_no) WHERE ref_no IS NOT NULL;
CREATE INDEX finance_settings_recent ON finance_settings (community_id, created_at DESC);
SELECT use_row_stamps('finance_settings');

