-- Electricity Bill  (collection: electricityBills)
CREATE TABLE electricity_bills (
  id                           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  community_id                 uuid NOT NULL REFERENCES communities (id),
  ref_no                       text,                                  -- the number people quote (from number_series)
  service                      text NOT NULL,   -- Supply
  service_no                   text NOT NULL,   -- Service connection no.
  period                       text NOT NULL,   -- Bill month (e.g. 2026-09)
  bill_date                    date NOT NULL,   -- Bill date
  due_date                     date NOT NULL,   -- Due date
  units                        numeric(16,4) NOT NULL,   -- Units imported / consumed (kWh)
