  other_charges                numeric(16,4),   -- Taxes, duty, penalty, other (₹)
  amount                       numeric(16,4) NOT NULL CHECK (amount >= 0),   -- Total payable (₹)
  status                       text NOT NULL,   -- Payment status
  paid_on                      date,   -- Paid on
  paid_from                    text,   -- Paid from account
  payment_ref                  text,   -- Payment reference / UTR
  cost_per_unit                numeric(16,4),   -- Cost per unit (₹)
  bill_file                    jsonb CHECK (jsonb_typeof(bill_file) IN ('array', 'object')),   -- Bill copy
  notes                        text,   -- Notes
  custom                       jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(custom) = 'object'),
  created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid, version integer NOT NULL DEFAULT 0,
  UNIQUE (community_id, id)
);
CREATE UNIQUE INDEX electricity_bills_ref ON electricity_bills (community_id, ref_no) WHERE ref_no IS NOT NULL;
