  backup_hours                 numeric(16,4),   -- Backup / battery hours (UPS)
  battery_changed              date,   -- Battery last changed
  make                         text,   -- Make
  model                        text,   -- Model
  serial_no                    text,   -- Serial no.
  rating                       text,   -- Rating (kW / HP / capacity)
  install_date                 date,   -- Installed on
  warranty_until               date,   -- Warranty until
  warranty_provider            text,   -- Warranty by (supplier / manufacturer)
  warranty_terms               text,   -- Warranty terms (what is covered, claim contact)
  amc_vendor                   text,   -- Service / AMC vendor
  last_service                 date,   -- Last serviced
  next_service                 date,   -- Next service due
  status                       text NOT NULL,   -- Condition
  faulty                       numeric(16,4),   -- How many of the quantity are faulty (groups)
  serves                       text[] NOT NULL DEFAULT '{}',   -- Serves (blocks or unit numbers that lose supply when this fails)
  close_valve                  text,   -- Close this valve first (isolation valve)
  last_inspected               date,   -- Last inspected
  shape                        text,   -- Position on plan
  breaks                       text,   -- Marked breaks
  plan_id                      uuid,   -- Plan
  spares                       text,   -- Spares to keep / spares used
  history                      text,   -- Service & repair history
  files                        jsonb CHECK (jsonb_typeof(files) IN ('array', 'object')),   -- Manuals, invoices, warranty
  custom                       jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(custom) = 'object'),
  created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid, version integer NOT NULL DEFAULT 0,
  UNIQUE (community_id, id)
);
