-- Cultural Events  (collection: culturalEvents)
CREATE TABLE cultural_events (
  id                           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  community_id                 uuid NOT NULL REFERENCES communities (id),
  ref_no                       text,                                  -- the number people quote (from number_series)
  name                         text NOT NULL,   -- Event name
  type                         text NOT NULL,   -- Type
  start_date                   date NOT NULL,   -- Starts
  end_date                     date,   -- Ends
  start_time                   time,   -- Start time
  end_time                     time,   -- End time
  repeat                       text,   -- Repeats (e.g. a weekly abhishekam)
  repeat_until                 date,   -- Repeats until (blank = ongoing)
  venue                        text,   -- Venue
  status                       text NOT NULL,   -- Status
  visibility                   text NOT NULL,   -- Visible to residents
  size                         text,   -- Size
  series                       text,   -- Same event each year (name without the year)
  budget                       numeric(16,4) CHECK (budget >= 0),   -- Budget / estimate (₹)
  historical_actual            numeric(16,4),   -- Actual spend from earlier records (₹) — overrides the expense list
  credited_amount              numeric(16,4) CHECK (credited_amount >= 0),   -- Unused budget credited back (₹)
  credited_at                  text,   -- Credited on
  credited_by                  text,   -- Credited by
  credit_note                  text,   -- Credit note
  target_collection            numeric(16,4),   -- Collection target (₹)
  upi_id                       text,   -- UPI id for payments (e.g. society@bank)
  fund                         text,   -- Fund this event spends from
  final_over                   numeric(16,4),   -- Treasurer approval needed for expenses over (₹) — 0 = every expense
  upi_payee                    text,   -- Payee name shown in the UPI app
  gateway                      text,   -- Online payment gateway
  programme_status             text,   -- Programme / agenda (no longer used)
  default_people               numeric(16,4),   -- People expected per villa at each programme item (default; blank = jus
  brochure_status              text,   -- Brochure
  brochure_published_at        text,   -- Brochure published / republished on
  brochure_version             numeric(16,4),   -- Brochure version
  show_brochure                text,   -- Show Brochure tab to residents
  show_programme               text,   -- Show Programme tab to residents
  show_offerings               text,   -- Show Seva offerings tab to residents
  show_volunteers              text,   -- Show Volunteer seva tab to residents
  show_donations               text,   -- Show Donations tab to residents
  show_photos                  text,   -- Show Photos tab to residents
  photos_by                    text,   -- Who can add photos
  offerings_title              text,   -- Offerings section title
  offerings_intro              text,   -- Offerings section introduction
  description                  text,   -- About the event
  collected                    numeric(16,4),   -- Collected (₹)
  pledged                      numeric(16,4),   -- Pledged, not yet received (₹)
  families                     numeric(16,4),   -- Devotee families (any pledge)
  donors                       numeric(16,4),   -- Contributing households
  spent                        numeric(16,4),   -- Spent (₹)
  custom                       jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(custom) = 'object'),
  created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid, version integer NOT NULL DEFAULT 0,
  UNIQUE (community_id, id)
);
